        links = r.get('links') or []
        if body or links: ok_pages += 1
        if method == 'sitemap':
            for block in re.findall(r'<url>(.*?)</url>', body, flags=re.S) or []:
                loc = re.search(r'<loc>\s*([^<\s]+)\s*</loc>', block); mod = re.search(r'<lastmod>\s*([^<\s]+)\s*</lastmod>', block)
                if loc and (not prof_pat or re.search(prof_pat, loc.group(1))):
                    lm = (mod.group(1)[:10] if mod else '')
                    profiles[loc.group(1)] = lm; newest = max(newest, lm)
            if not profiles:   # sitemap without <url> blocks: plain locs
                for loc in re.findall(r'<loc>\s*([^<\s]+)\s*</loc>', body):
                    if not prof_pat or re.search(prof_pat, loc): profiles[loc] = ''
        else:
            for l in links:
                href = (l.get('href') or '').strip(); text = re.sub(r'\s+', ' ', (l.get('text') or '')).strip()
                h = host(href)
                if not h: continue
                if method == 'profile_pages' or (link_pat and link_pat != 'external'):
                    if re.search(prof_pat, href) and (h == firm_dom or h.endswith('.' + firm_dom)): profiles.setdefault(href, '')
                else:   # 'external': off-site company websites linked from the directory
                    if h == firm_dom or h.endswith('.' + firm_dom) or any(s in h for s in SOCIAL): continue
                    name = text if text and text.lower() not in ('visit website', 'website', 'visit', 'learn more', 'read more', '→') else ''
                    companies.setdefault(h, {'company': name, 'website': h})
                    if name and not companies[h]['company']: companies[h]['company'] = name
    found = len(companies) + len(profiles)
    # Profiles to open this run: ones never read before (sitemaps often stamp every URL with the same lastmod), capped.
    todo = sorted((u for u in profiles if u not in seen), key=lambda u: (profiles[u], u), reverse=True)
    return {'companies': [{'company': v['company'], 'website': v['website']} for v in companies.values()],
            'profile_urls_found': len(profiles), 'profiles_to_open': todo[:300], 'profiles_deferred': max(0, len(todo) - 300),
            'pages_read': ok_pages, 'found': found, 'newest_lastmod': newest, 'profiles_already_seen': len([u for u in profiles if u in seen])}

import re

SOCIAL = ('linkedin.com', 'twitter.com', 'x.com', 'facebook.com', 'instagram.com', 'youtube.com', 'medium.com', 'github.com', 'tiktok.com',
          'crunchbase.com', 'angel.co', 'wellfound.com', 'google.com', 'apple.com', 'startupschool.org', 'amazon.com', 'bit.ly', 'calendly.com')

def _items(x):
    if isinstance(x, list): return x
    if isinstance(x, dict):
        for k in ('results', 'entries', 'items', 'outputs'):
            if isinstance(x.get(k), list): return x[k]
        return [x]
    return []

def host(u):
    u = re.sub(r'^[a-z]+://', '', (u or '').strip().lower()); u = re.sub(r'^www\d?\.', '', u)
    return u.split('/')[0].split('?')[0].split('#')[0]

SEASON = re.compile(r'(Winter|Summer|Spring|Fall|Autumn)\s*(20\d\d)(?!\d)')
FUND = re.compile(r'\bFund\s+([IVX]+|\d+)\b')
STATUS = re.compile(r'(Active|Acquired|Inactive|Public|Exited|Closed)(?=[A-Z]|\s|$)')

def handler(context):
    g = context.get_input
    firm_dom = host(g('firm_domain'))
    urls = g('profiles_to_open') or []
    listed = g('companies') or []
    found = int(g('found') or 0); pages_read = int(g('pages_read') or 0)
    last = int(g('last_count') or 0); expected = int(g('expected_count') or 0)
    recipe_known = bool(g('method'))
    out, failed_profiles = [], 0
    for i, r in enumerate(_items(g('profile_scrape'))):
        r = r.get('result', r) if isinstance(r, dict) else {}
        url = urls[i] if i < len(urls) else ''
        if not isinstance(r, dict) or not (r.get('bodyText') or r.get('links')):
            failed_profiles += 1; continue
        title = re.split(r'\s[:|–-]\s|:', r.get('title') or '')[0].strip()
        site = ''
        for l in r.get('links') or []:
            h = host(l.get('href'))
            if h and h != firm_dom and not h.endswith('.' + firm_dom) and not any(s in h for s in SOCIAL):
                site = h; break
        body = r.get('bodyText') or ''
        m = SEASON.search(body) or FUND.search(body); s = STATUS.search(body)
        batch = (m.group(1) + ' ' + m.group(2)) if m and m.re is SEASON else (m.group(0) if m else '')
        out.append({'company': title, 'website': site, 'fund_or_batch': batch, 'status': s.group(1) if s else '', 'profile_url': url})
    for c in listed:
        out.append({'company': c.get('company') or c.get('website') or '', 'website': c.get('website') or '', 'fund_or_batch': '', 'status': '', 'profile_url': ''})
    # Health: is the recipe still reading this site?
    reasons = []
    if pages_read == 0: reasons.append('the directory fetch returned nothing')
    if found == 0: reasons.append('no company links matched the recipe')
    if last and found < 0.5 * last: reasons.append(f'found {found} vs {last} last time')
    if urls and failed_profiles > 0.5 * len(urls): reasons.append(f'{failed_profiles} of {len(urls)} profile pages failed')
    if not recipe_known: status = 'no_recipe'
    elif reasons: status = 'broken'
    elif expected and found < 0.8 * expected: status = 'partial'
    else: status = 'ok'
    return {'directory_companies': out, 'directory_status': status, 'directory_found': found, 'profiles_read': len(urls) - failed_profiles,
            'health_reason': '; '.join(reasons) or ('below the site\'s stated total' if status == 'partial' else ''), 'needs_fallback': status in ('broken', 'no_recipe')}

def _items(x):
    if isinstance(x, list): return x
    if isinstance(x, dict):
        for k in ('results', 'entries', 'items', 'outputs'):
            if isinstance(x.get(k), list): return x[k]
        return [x]
    return []

def _clean(v):
    return str(v or '').replace('\t', ' ').replace('\n', ' ')

def row(lane, name, domain, date='', rnd='', url='', rid='', note=''):
    return '\t'.join(_clean(x) for x in (lane, name, domain, date, rnd, url, rid, note))

def handler(context):
    g = context.get_input
    rows = []
    for src in ('dealroom_p1', 'dealroom_more'):
        for r in _items(g(src)):
            r = r.get('result', r) if isinstance(r, dict) else {}
            for x in (r.get('data') or []) if isinstance(r, dict) else []:
                if (x.get('type') or 'company') == 'company':
                    rows.append(row('dealroom', x.get('name'), x.get('website_url'), note='Dealroom investor investments'))
    for r in _items(g('pitchbook')):
        r = r.get('result', r) if isinstance(r, dict) else r
        for x in (r if isinstance(r, list) else (r or {}).get('items') or []) if r else []:
            if isinstance(x, dict):
                rows.append(row('pitchbook', x.get('companyName'), x.get('website') or x.get('companyWebsite'),
                                (x.get('investmentDate') or x.get('investorSince') or '')[:10], rid=x.get('investmentDealId') or x.get('companyId'), note='PitchBook active investment'))
    sf = g('salesforce') or {}
    sf = sf.get('result', sf) if isinstance(sf, dict) else {}
    total = 0
    for x in (sf.get('rows') or []) if isinstance(sf, dict) else []:
        total = max(total, int(x.get('TOTAL_MATCHES') or 0))
        rows.append(row('salesforce', x.get('NAME'), x.get('DOMAIN'), x.get('LAST_FUNDING_DATE'), x.get('LAST_FUNDING_TYPE'), x.get('SOURCE_LINK'), x.get('ID'),
                        'Salesforce investors: ' + _clean(x.get('INVESTORS'))[:200]))
    sf_rows = sum(1 for r in rows if r.startswith('salesforce\t'))
    fails = {k: int((g(k) or {}).get('failedCount') or 0) if isinstance(g(k), dict) else 0 for k in ('dealroom_p1', 'dealroom_more', 'pitchbook', 'linkedin', 'google')}
    return {'provider_rows': rows, 'salesforce_total': total, 'salesforce_rows': sf_rows,
            'failed_counts': {'dealroom': fails['dealroom_p1'] + fails['dealroom_more'], 'pitchbook': fails['pitchbook'], 'linkedin': fails['linkedin'], 'google': fails['google']}}

import json, re
from datetime import datetime, timezone

LANE_SOURCE = {'official_page': 'official_page', 'official_portfolio': 'official_portfolio', 'google': 'google', 'linkedin': 'linkedin',
               'x': 'x', 'dealroom': 'dealroom', 'pitchbook': 'pitchbook', 'salesforce': 'salesforce'}

def _items(x):
    if isinstance(x, list): return x
    if isinstance(x, dict):
        for k in ('results', 'entries', 'items', 'outputs'):
            if isinstance(x.get(k), list): return x[k]
        return [x]
    return []

def body(kind, rows):
    return json.dumps({'p_kind': kind, 'p_rows': rows}, separators=(',', ':'))

def chunk(rows, n=300):
    return [rows[i:i + n] for i in range(0, len(rows), n)]

def handler(context):
    g = context.get_input
    firm = g('firm_listed') or g('firm') or ''
    run_id = g('run_id') or ''
    now = datetime.now(timezone.utc).isoformat()
    meta = []
    # 1. Identity, when this run re-researched it.
    if g('identity_refreshed') and g('official_name'):
        split = lambda s: [x.strip() for x in (s or '').split('|') if x.strip()]
        meta.append(body('firm_identity', [{'firm': firm, 'official_name': g('official_name'), 'firm_domain': g('firm_domain'), 'firm_type': g('firm_type'),
            'aliases': split(g('aliases')), 'alias_collisions': split(g('alias_collisions')), 'crunchbase_url': g('crunchbase_url') or '',
            'linkedin_url': g('linkedin_url') or '', 'x_url': g('x_url') or '', 'portfolio_url': g('portfolio_url') or '', 'identity_confidence': g('identity_confidence') or ''}]))
    # 2. Sources: the directory recipe and its health, and each announcement page with its checkpoint.
    srcs = []
    dstat = g('directory_status') or ''
    if g('directory_source_url'):
        row = {'firm': firm, 'url': g('directory_source_url'), 'source_type': 'portfolio_directory',
               'outcome': 'ok' if dstat == 'ok' else ('failed' if dstat == 'broken' else 'partial'),
               'last_count': int(g('directory_found') or 0)}
        row['last_success_at' if dstat in ('ok', 'partial') else 'last_failure_at'] = now
        if g('is_new_recipe'):
            row.update({k: g('recipe_' + k) for k in ('method', 'list_url', 'link_pattern', 'profile_pattern', 'recipe_notes')})
            row['needs_js'] = bool(g('recipe_needs_js')); row['expected_count'] = int(g('recipe_expected_count') or 0)
        srcs.append(row)
    try: news = json.loads(g('news_sources_json') or '[]')
    except (ValueError, TypeError): news = []
    for n in news if isinstance(news, list) else []:
        if not isinstance(n, dict) or not n.get('url'): continue
        ok = n.get('status') == 'ok'
        r = {'firm': firm, 'url': n['url'], 'source_type': n.get('source_type') or 'news', 'outcome': 'ok' if ok else 'failed'}
        r['last_success_at' if ok else 'last_failure_at'] = now
        if ok and re.match(r'^\d{4}-\d{2}-\d{2}$', n.get('newest_date') or ''):
            r['checkpoint_date'] = n['newest_date']; r['checkpoint_url'] = n.get('newest_url') or ''
        srcs.append(r)
    if srcs: meta.append(body('firm_sources', srcs))
    # 3. Per-source run status (a failed source is recorded as failed, never as zero companies).
    counts = g('lane_counts') or {}; caps = g('caps') or {}
    fails = {'dealroom': g('dealroom_failed'), 'pitchbook': g('pitchbook_failed'), 'linkedin': g('linkedin_failed'), 'google': g('google_failed')}
    runs = []
    for lane, src in LANE_SOURCE.items():
        c = int(counts.get(lane) or 0)
        if lane == 'official_portfolio': st = {'ok': 'ok', 'partial': 'partial', 'broken': 'failed', 'no_recipe': 'partial'}.get(dstat, 'ok' if c else 'no_new')
        elif lane == 'official_page': st = {'Read through window': 'ok', 'Partial: stopped early': 'partial', 'Fetch failed': 'failed'}.get(g('archive_status') or '', 'ok' if c else 'no_new')
        elif int(fails.get(lane) or 0) > 0 and c == 0: st = 'failed'
        elif (lane == 'dealroom' and caps.get('dealroom_capped')) or (lane == 'salesforce' and caps.get('salesforce_capped')): st = 'capped'
        else: st = 'ok' if c else 'no_new'
        runs.append({'run_id': run_id, 'firm': firm, 'source': src, 'status': st, 'companies': c, 'new_companies': 0,
                     'cap_hit': st == 'capped', 'checkpoint': '', 'error': ''})
    if run_id: meta.append(body('source_runs', runs))
    # 4. Roster evidence for every verified company, grouped by company so parallel batches never share one.
    ver = _items(g('verified')); tv = g('to_verify') or []
    roster, verifs = [], []
    for i, c in enumerate(tv):
        v = ver[i] if i < len(ver) else {}
        v = v.get('output', v) if isinstance(v, dict) else {}
        if not isinstance(v, dict) or v.get('backing') not in ('Confirmed', 'Not confirmed', 'Different firm', 'Unclear'): continue
        domain = v.get('company_domain') or c.get('domain') or ''
        name = v.get('company_name') or c.get('name') or ''
        group = []
        for e in c.get('evidence') or []:
            src = LANE_SOURCE.get(e.get('lane'))
            if not src: continue
            ref = e.get('id') or e.get('url') or (src + ':' + (domain or name))
            group.append({'firm': firm, 'source': src, 'source_ref': ref[:500], 'company_name': name, 'domain': domain,
                          'evidence_url': e.get('url') or '', 'observed_at': now, 'run_id': run_id or None,
                          'round_or_batch': e.get('round') or '', 'invested_at': e.get('date') if re.match(r'^\d{4}-\d{2}-\d{2}$', e.get('date') or '') else None,
                          'payload': {'note': e.get('note') or '', 'role': e.get('role') or '', 'event': e.get('event') or ''}})
        if group: roster.append(group)
        verifs.append({'firm': firm, 'domain': domain, 'company_name': name, 'backing': v.get('backing'), 'relationship': v.get('relationship') or '',
                       'backing_source_url': v.get('backing_source_url') or '', 'latest_round_type': v.get('latest_round_type') or '',
                       'latest_round_date': v.get('latest_round_date') or '', 'latest_round_amount_usd': v.get('latest_round_amount_usd') or 0,
                       'latest_round_leads': v.get('latest_round_leads') or '', 'latest_round_source_url': v.get('latest_round_source_url') or '',
                       'firm_in_latest_round': v.get('firm_in_latest_round') or 'Unknown', 'signal_key': c.get('latest_hint') or '', 'run_id': run_id or None})
    roster_bodies, cur, n = [], [], 0
    for grp in roster:
        if n + len(grp) > 400 and cur: roster_bodies.append(body('roster', cur)); cur, n = [], 0
        cur += grp; n += len(grp)
    if cur: roster_bodies.append(body('roster', cur))
    return {'meta_writes': meta, 'roster_writes': roster_bodies, 'verification_writes': [body('verifications', ch) for ch in chunk(verifs)],
            'counts': {'meta': len(meta), 'roster_rows': sum(len(x) for x in roster), 'verifications': len(verifs), 'sources': len(srcs)}}
